.stl .dm-main{gap:10px}
.stl-row{display:flex;align-items:center;gap:10px;background:var(--dm-surface);border-radius:var(--dm-r-pill);box-shadow:var(--dm-shadow);height:40px;padding:0 14px 0 13px;font-size:13.5px;min-width:250px;transition:box-shadow .3s}
@media (hover:hover) and (pointer:fine){.stl-row:hover{box-shadow:var(--dm-shadow-pop)}}
.stl-g{width:16px;display:grid;place-items:center;color:var(--dm-fg)}
.stl-t{flex:1;text-align:left}
