/* ---------- Decision prompt ---------- */
/* the agent asks in the chat: no container; with .panel it becomes a card */
.dpx{padding:var(--dm-s-4) 0;display:flex;flex-direction:column;gap:var(--dm-s-3);outline:0;border-radius:var(--dm-r-in)}
.dpx.panel{padding:var(--dm-s-4);border-radius:var(--dm-r-card)}
.dpx:focus-visible{outline:2px solid var(--dm-focus);outline-offset:6px}
.dpx-h{display:flex;align-items:center;justify-content:space-between}
.dpx-k{font-size:12px}
.dpx-dots{display:flex;gap:var(--dm-s-1)}
.dpx-dots i{width:6px;height:6px;border-radius:3px;background:var(--dm-line);transition:width .45s var(--dm-ease),background .35s}
.dpx-dots i.on{width:16px;background:var(--dm-accent-mark,var(--dm-accent))}
.dpx-dots i.done{background:var(--dm-accent-mark,var(--dm-accent));opacity:.4}
.dpx-body{min-height:168px}
.dpx-q{font-size:14px;font-weight:500;margin-bottom:10px;text-wrap:balance}
.dpx-o{display:flex;align-items:center;gap:10px;width:calc(100% + 20px);margin-inline:-10px;padding:9px 10px;border-radius:var(--dm-r-in);font-size:13.5px;text-align:left;color:var(--dm-fg2);transition:background .25s,color .25s}
@media (hover:hover) and (pointer:fine){.dpx-o:hover{background:var(--dm-row);color:var(--dm-fg)}}
.dpx-o.on{background:var(--dm-sel);color:var(--dm-fg)}
.dpx-o .kbd{width:20px;text-align:center;transition:background .25s,color .25s}
.dpx-o.on .kbd{background:var(--dm-accent);color:var(--dm-on-accent)}
.dpx-o .d{margin-left:auto;font-size:12px;color:var(--dm-muted)}
.dpx-f{display:flex;justify-content:flex-end;gap:6px}
.dpx-sum{display:flex;flex-direction:column;gap:6px}
.dpx-sr{display:flex;gap:10px;font-size:13px;padding:7px 0;border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.dpx-sr:last-child{border:0}
.dpx-sr span{color:var(--dm-muted);width:92px;flex:none}
.dpx-run{display:flex;align-items:center;gap:var(--dm-s-2);font-size:13px;margin-top:6px}

