/* ---------- Metric insight ---------- */
.mix{padding:var(--dm-s-4);display:flex;flex-direction:column;gap:10px}
.mix-h{display:flex;align-items:center;justify-content:space-between;font-size:12.5px}
.mix-rg button{font-size:11.5px;padding:0 var(--dm-s-2);height:24px}
.mix-v{display:flex;align-items:center;gap:var(--dm-s-2)}
.mix-v b{font-size:14px;font-weight:500;letter-spacing:-.02em}
.mix-ch{position:relative;height:90px;cursor:crosshair}
.mix-svg{width:100%;height:100%;display:block;overflow:visible}
.mix-l{stroke-dasharray:var(--dm-len);stroke-dashoffset:var(--dm-len);transition:stroke-dashoffset 1.2s var(--dm-ease)}
.mix-ch.in .mix-l{stroke-dashoffset:0}
.mix-a{opacity:0;transition:opacity .8s .5s}
.mix-ch.in .mix-a{opacity:1}
.mix-x{opacity:0;transition:opacity .2s}
@media (hover:hover) and (pointer:fine){.mix-ch:hover .mix-x,.mix-ch:hover .mix-dot{opacity:1}}
.mix-dot{position:absolute;width:9px;height:9px;margin:-4.5px;border-radius:50%;background:var(--dm-surface);box-shadow:0 0 0 2px var(--dm-accent-mark,var(--dm-accent));opacity:0;transition:opacity .2s;pointer-events:none}
/* the change it explains is marked where it happened: a small date label at the top of a dashed guide down through the chart */
.mix-mk{position:absolute;top:-14px;bottom:0;display:flex;flex-direction:column;align-items:center;transform:translateX(-50%);opacity:0;transition:opacity .4s 1.1s;pointer-events:none}
.mix-mk b{pointer-events:auto;display:inline-flex;align-items:center;gap:var(--dm-s-1);height:20px;padding:0 7px;border-radius:var(--dm-r-pill);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:11.5px;font-weight:500;color:var(--dm-fg2);white-space:nowrap}
.mix-mk b svg{width:10px;height:10px;color:var(--dm-accent-fg,var(--dm-accent))}
.mix-mk::after{content:"";flex:1;border-left:1px dashed color-mix(in srgb,var(--dm-faint) 50%,transparent)}
.mix-ch.in .mix-mk{opacity:1}
.mix-ins{display:flex;gap:var(--dm-s-2);align-items:flex-start;font-size:13px;line-height:1.5;color:var(--dm-fg2)}
.mix-ic{color:var(--dm-accent-fg,var(--dm-accent));display:grid;margin-top:2px}
.mix-why{align-self:flex-start}
/* a lighter button than the soft pill, like the other quiet asks */
.pill.soft.mix-why{background:var(--dm-chip);box-shadow:none}
.pill.soft.mix-why[aria-expanded="true"]{background:var(--dm-hover)}
@media (hover:hover) and (pointer:fine){.pill.soft.mix-why:hover{background:var(--dm-hover)}}
.mix-rs{display:flex;flex-direction:column;gap:6px;padding-top:2px}
.mix-r{display:flex;align-items:center;gap:10px;font-size:12.5px}
.mix-r .t{flex:1;min-width:0}
.mix-r .bar{width:70px;height:5px;border-radius:3px;background:var(--dm-line);overflow:hidden;flex:none}
.mix-r .bar i{display:block;height:100%;border-radius:3px;transform-origin:left;animation:ssrel .8s var(--dm-ease) both}
.mix-r .v{width:44px;text-align:right;font-size:12px;color:var(--dm-fg2)}
@keyframes ssrel{from{transform:scaleX(0)}}

