/* ---------- Run cost ---------- */
.rc{padding:18px}
.rc-h{display:flex;align-items:center;justify-content:space-between;font-size:12.5px}
.rc-st{transition:background .3s,color .3s}
/* the status dot is a mark: paused at the cap it takes the bright orange of the bar, while the words keep the darker text orange */
