.rc-rows div{display:flex;justify-content:space-between;padding:5px 0;font-size:13px;color:var(--dm-fg2)}
.rc-rows .num{color:var(--dm-fg)}
.rc-f{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:var(--dm-s-3);padding-top:var(--dm-s-3);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.rc-cap-t{display:flex;align-items:center;gap:9px;font-size:13px;color:var(--dm-fg2);cursor:pointer}

