/* ---------- Date picker ---------- */
/* one field, as wide as the other single fields; its script keeps it centred in its stage and glides it up as the calendar opens */
.dpk{position:relative;width:100%;max-width:var(--dm-field-w);margin:0 auto}
.dpk-f{display:flex;align-items:center;gap:10px;width:100%;height:var(--dm-field-h);padding:0 var(--dm-s-3);border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);font-size:13.5px;transition:box-shadow var(--dm-t-fast)}
@supports (corner-shape:squircle){.dpk-f{corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
/* a dropdown's field steps up its edge while it has the focus or its calendar is open; it takes no ring */
.dpk-f:focus-visible{outline:0;box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.dpk-f>svg:first-child{color:var(--dm-muted)}
.dpk-val{flex:1;text-align:left;color:var(--dm-fg)}
.dpk-val.ph{color:var(--dm-muted)}
.dpk-f>svg:last-child{color:var(--dm-muted)}
.dpk-pop{width:100%;padding:10px;background:var(--dm-surface)}
.dpk-nl{width:100%;height:32px;border:0;outline:0;border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);padding:0 10px;font:inherit;font-size:13px;color:var(--dm-fg);transition:box-shadow var(--dm-t-fast)}
@supports (corner-shape:squircle){.dpk-nl{corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
.dpk-nl::placeholder{color:var(--dm-muted)}
.dpk-nl:focus{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.dpk-qk{display:flex;gap:var(--dm-s-1);margin:var(--dm-s-2) 0}
.dpk-mh{display:flex;align-items:center;justify-content:space-between;margin:var(--dm-s-1) 0}
.dpk-mh b{font-weight:500;font-size:13px}
.dpk-mh .ib{width:26px;height:26px}
.dpk-wd,.dpk-g{display:grid;grid-template-columns:repeat(7,1fr);text-align:center}
.dpk-wd{font-size:11px;margin-bottom:2px}
.dpk-vp{overflow:hidden}
.dpk-g{gap:2px 0}
.dpk-g.in-l{animation:dpkl .4s var(--dm-ease) both}.dpk-g.in-r{animation:dpkr .4s var(--dm-ease) both}
@keyframes dpkl{from{opacity:0;transform:translateX(-24px);filter:blur(3px)}}
@keyframes dpkr{from{opacity:0;transform:translateX(24px);filter:blur(3px)}}
.dpk-d{height:32px;border-radius:calc(9px * var(--dm-rk));font-size:12.5px;color:var(--dm-fg);transition:background .2s,color .2s;position:relative}
@media (hover:hover) and (pointer:fine){.dpk-d:hover{background:var(--dm-row)}}
/* the days fill the month's sliding view, which would cut an outside ring: theirs is drawn inside */
.dpk-d:focus-visible{outline-offset:-2px}
.dpk-d.o{color:var(--dm-muted)}
.dpk-d.t::after{content:"";position:absolute;left:50%;bottom:4px;width:4px;height:4px;margin-left:-2px;border-radius:50%;background:var(--dm-accent-mark,var(--dm-accent))}
.dpk-d.s{background:var(--dm-accent);color:var(--dm-on-accent)}
.dpk-d.s::after{background:var(--dm-on-accent)}
.dpk-d.s{animation:dpks .35s var(--dm-ease)}
/* on the picked day the inside ring would sit on the accent fill: a surface gap inside it keeps it seen */
.dpk-d.s:focus-visible{box-shadow:inset 0 0 0 3.5px var(--dm-surface)}
@keyframes dpks{from{transform:scale(.8)}}

