/* ---------- page shell ---------- */
:where([data-c]) *{box-sizing:border-box}
:where([data-c]) button,:where([data-c]) input,:where([data-c]) textarea,:where([data-c]) select{font:inherit;color:inherit}
:where([data-c]) button{background:none;border:0;padding:0;cursor:pointer}
/* one weight for emphasis: medium, never bold */
:where([data-c]) b,:where([data-c]) strong{font-weight:500}
:where([data-c]) :focus-visible{outline:2px solid var(--dm-focus);outline-offset:2px;border-radius:calc(6px * var(--dm-rk))}
/* a field shows the focus with its own edge, which steps up to --dm-field-line-strong, so it never takes the ring as well */
:where([data-c]) :focus-visible:is(input:not([type="checkbox"],[type="radio"],[type="range"],[type="file"],[type="button"],[type="submit"],[type="reset"]),textarea,select,[contenteditable]:not([contenteditable="false"])){outline:0}
.stage-in{width:100%;max-width:440px;min-width:0;position:relative;container-type:inline-size}
.card.wide .stage-in{max-width:720px}

/* ---------- icons ---------- */
.i{width:16px;height:16px;flex:none;display:inline-block;vertical-align:-3px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
.i.s{width:14px;height:14px}.i.xs{width:12px;height:12px}.i.l{width:18px;height:18px}
.brand{width:16px;height:16px;display:block;flex:none}
.flag{width:20px;height:15px;border-radius:3px;object-fit:cover;display:block;flex:none;box-shadow:0 0 0 1px rgba(0,0,0,.08)}

/* ---------- primitives ---------- */
.mono{font-family:var(--dm-mono)}
.sp{flex:1}
.num{font-variant-numeric:tabular-nums}
.muted{color:var(--dm-muted)}.fg2{color:var(--dm-fg2)}
.panel{background:var(--dm-surface);border-radius:var(--dm-r-card);box-shadow:var(--dm-shadow);position:relative}
.ib{width:30px;height:30px;border-radius:50%;display:inline-grid;place-items:center;color:var(--dm-fg2);transition:background var(--dm-t-fast),color var(--dm-t-fast),transform .15s}
@media (hover:hover) and (pointer:fine){.ib:hover{background:var(--dm-row);color:var(--dm-fg)}}
.ib:active{transform:scale(.94)}
.ib.fill{background:var(--dm-soft);box-shadow:var(--dm-soft-ring)}
@media (hover:hover) and (pointer:fine){.ib.fill:hover{background:var(--dm-soft-h)}}
.ib.on{background:var(--dm-accent-bg);color:var(--dm-accent-fg,var(--dm-accent))}
.chip{display:inline-flex;align-items:center;gap:6px;height:30px;padding:0 var(--dm-s-3);border-radius:var(--dm-r-pill);font-size:13px;color:var(--dm-fg2);background:var(--dm-chip);white-space:nowrap;transition:background var(--dm-t-fast),color var(--dm-t-fast),box-shadow var(--dm-t-fast)}
