/* ---------- Buttons ---------- */
.btx{display:flex;flex-direction:column;gap:14px;width:100%}
.btx-row{display:flex;align-items:center;gap:var(--dm-s-2);flex-wrap:wrap}
.btx-l{width:74px;font-size:12px;flex:none}
@media (max-width:520px){.btx-l{width:100%}}
.btx-lg{height:40px;padding:0 18px;font-size:14px}
.btx-load,.btx-copy{min-width:100px;transition:min-width .4s var(--dm-ease),background .3s}
.btx-load .spin{width:13px;height:13px;border-color:color-mix(in srgb,var(--dm-on-ink) 30%,transparent);border-top-color:var(--dm-on-ink)}
.pill.btx-load.ok{background:color-mix(in srgb,var(--dm-ok) 16%,var(--dm-surface));color:var(--dm-ok);opacity:1}
@media (hover:hover) and (pointer:fine){.pill.btx-load.ok:hover{background:color-mix(in srgb,var(--dm-ok) 16%,var(--dm-surface));color:var(--dm-ok);opacity:1}}
.btx-load.busy{cursor:progress}
.btx-ask{min-width:110px;position:relative;overflow:hidden;isolation:isolate;transition:min-width .4s var(--dm-ease),background .3s}
.btx-ask::after{content:"";position:absolute;inset:0;background:linear-gradient(105deg,transparent 30%,rgba(255,255,255,.42) 50%,transparent 70%);transform:translateX(-120%);pointer-events:none}
.btx-ask:focus-visible::after{transform:translateX(120%);transition:transform .85s var(--dm-ease)}
@media (hover:hover) and (pointer:fine){.btx-ask:hover::after{transform:translateX(120%);transition:transform .85s var(--dm-ease)}}
.btx-ask:is(.busy,.done)::after{display:none}
.btx-trial,.btx-run{min-width:96px;transition:min-width .4s var(--dm-ease),background .3s,opacity .2s}
.btx-trial .spin{border-color:color-mix(in srgb,var(--dm-on-accent) 35%,transparent);border-top-color:var(--dm-on-accent)}
.btx-run .spin{width:13px;height:13px;border-color:color-mix(in srgb,var(--dm-on-ink) 30%,transparent);border-top-color:var(--dm-on-ink)}
.btx-run.busy{cursor:pointer}
.btx-run .sq{width:9px;height:9px;border-radius:2px;background:currentColor;flex:none}
.btx-pv{min-width:84px}
.pill.btx-pv[aria-pressed="true"]{background:var(--dm-soft-h)}
.btx-live{position:relative;width:7px;height:7px;border-radius:50%;background:var(--dm-ok);flex:none}
.btx-live::after{content:"";position:absolute;inset:0;border-radius:50%;background:inherit;animation:ping 1.8s var(--dm-ease) infinite}
.btx-share{min-width:72px}
/* a pill that swap() crossfades keeps its flex layout, so the icon put back in it later keeps its gap */
.btx-row .pill.sw{display:inline-flex}
.btx-sp{min-width:210px}
.btx-fig{min-width:128px;transition:min-width .4s var(--dm-ease),background .3s}
.btx-fig .spin{width:13px;height:13px}
.btx-mp{min-width:200px}
.btx-mp .mi.del,.btx-mp .mi.del .i{color:var(--dm-bad)}
@media (hover:hover) and (pointer:fine){.btx-mp .mi.del:hover{background:var(--dm-bad-bg)}}
.ib.btx-more.done{color:var(--dm-ok)}
.pill.btx-ask.busy{background:var(--dm-accent-bg);color:var(--dm-accent-fg,var(--dm-accent));cursor:progress}
@media (hover:hover) and (pointer:fine){.pill.btx-ask.busy:hover{background:var(--dm-accent-bg);color:var(--dm-accent-fg,var(--dm-accent));cursor:progress}}
.pill.btx-ask.done{background:color-mix(in srgb,var(--dm-ok) 16%,var(--dm-surface));color:var(--dm-ok)}
@media (hover:hover) and (pointer:fine){.pill.btx-ask.done:hover{background:color-mix(in srgb,var(--dm-ok) 16%,var(--dm-surface));color:var(--dm-ok)}}
.btx-hold{position:relative;overflow:hidden;background:var(--dm-bad-bg);color:var(--dm-bad);user-select:none;-webkit-user-select:none;touch-action:none}
.btx-hold .fill{position:absolute;inset:0;background:var(--dm-bad);transform-origin:left;transform:scaleX(0);transition:transform .25s var(--dm-ease)}
.btx-hold.h .fill{transform:scaleX(1);transition:transform 1.2s linear}
.btx-hold .lb{position:relative;display:inline-flex;align-items:center;gap:7px;transition:color .3s}
.btx-hold.h .lb,.btx-hold.done .lb{color:#fff}
.btx-hold.done .fill{transform:scaleX(1)}

