/* ---------- Comments ---------- */
/* a thread on one spot of a design: the first comment, then its replies indented on a thin line. Each comment is an avatar,
   a name, a time and the text; its Agree button shows on hover or keyboard focus (always, on a touch screen) */
.cmx{padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-4);min-height:340px}
/* on a card the thread keeps the room its last reply takes, so it stays centred while replies arrive */
.stage-in>.cmx{min-height:inherit}
.cmx-h{display:flex;align-items:center;gap:var(--dm-s-2);font-size:13.5px;margin:calc(-1 * var(--dm-s-1)) calc(-1 * var(--dm-s-1)) 0 0}
.cmx-h b{font-weight:500}
.cmx-st{flex:1;font-size:12px;color:var(--dm-muted)}
.cmx-pin{width:20px;height:20px;border-radius:50% 50% 50% var(--dm-r-xs);background:var(--dm-accent);color:var(--dm-on-accent);display:grid;place-items:center;font-size:11px;font-weight:500;flex:none;transition:background var(--dm-t)}
.cmx.done .cmx-pin{background:var(--dm-ok);color:var(--dm-surface)}
.cmx-res{width:28px;height:28px;color:var(--dm-muted)}
.cmx-th{display:flex;flex-direction:column;gap:var(--dm-s-4);flex:1}
.cmx-rp{display:flex;flex-direction:column;gap:var(--dm-s-4);margin-left:var(--dm-s-3);padding-left:calc(var(--dm-s-5) + 1px);position:relative}
/* the replies' line starts just below the first comment's avatar, centred under it, and runs down beside every reply */
.cmx-th>.cmx-c:first-child{position:relative}
.cmx-th>.cmx-c:first-child:has(+ .cmx-rp)::before,.cmx-rp::before{content:'';position:absolute;width:1px;background:var(--dm-rail);pointer-events:none}
.cmx-th>.cmx-c:first-child:has(+ .cmx-rp)::before{left:calc(var(--dm-s-3) - .5px);top:calc(24px + var(--dm-s-1));bottom:calc(-1 * var(--dm-s-4))}
.cmx-rp::before{left:-.5px;top:0;bottom:0}
.cmx-c{display:flex;gap:var(--dm-s-3);min-width:0}
.cmx-c .av{width:24px;height:24px;font-size:10px}
.cmx-c .b{flex:1;display:flex;flex-direction:column;min-width:0}
.cmx-c .n{display:flex;align-items:center;gap:var(--dm-s-2);height:24px;font-size:13px}
.cmx-c .n b{font-weight:500;white-space:nowrap}
.cmx-c .n .t{font-size:12px;color:var(--dm-muted)}
.cmx-c .tx{font-size:13.5px;line-height:1.5;color:var(--dm-fg);overflow-wrap:anywhere}
.cmx-c .m{color:var(--dm-accent-fg,var(--dm-accent));background:var(--dm-sel);border-radius:var(--dm-r-xs);padding:0 2px}
.cmx-c.ag .tx .w{animation:cmw .4s var(--dm-ease) both}
@keyframes cmw{from{opacity:0;filter:blur(3px)}to{opacity:1;filter:none}}
.cmx-c .act{display:flex;flex-wrap:wrap;gap:var(--dm-s-2);margin-top:var(--dm-s-2)}
/* the quiet Agree button beside the time */
.cmx-tools{margin-left:auto;display:flex;gap:var(--dm-s-1);transition:opacity var(--dm-t-fast)}
.cmx-tools .ib{width:26px;height:26px;color:var(--dm-muted)}
.cmx-tools .ib[aria-pressed="true"]{color:var(--dm-fg)}
@media (hover:hover) and (pointer:fine){.cmx-tools{opacity:0}}
.cmx-c .n:focus-within .cmx-tools{opacity:1}
@media (hover:hover) and (pointer:fine){.cmx-c:hover .cmx-tools{opacity:1}}
/* how many agreed: a small chip under the text, a step stronger once you have */
.cmx-rs{display:flex;margin-top:var(--dm-s-2)}
.cmx-rs:has(.cmx-rc[hidden]){display:none}
.cmx-rc{display:inline-flex;align-items:center;gap:var(--dm-s-1);height:22px;padding:0 var(--dm-s-2);border-radius:var(--dm-r-pill);font-size:12px;color:var(--dm-fg2);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent);transition:box-shadow var(--dm-t-fast),color var(--dm-t-fast)}
