/* ---------- Agenda ---------- */
.agx{padding:var(--dm-s-3);display:flex;flex-direction:column;gap:var(--dm-s-2)}
.agx-h{display:flex;align-items:center;justify-content:space-between;padding:2px var(--dm-s-1)}
.agx-h>div{display:flex;flex-direction:column;font-size:13.5px}
.agx-h b{font-weight:500}
.agx-h .muted{font-size:12px}
.agx-list{display:flex;flex-direction:column;gap:var(--dm-s-1);position:relative}
.agx-e{display:grid;grid-template-columns:52px 3px 1fr;gap:10px;padding:var(--dm-s-2) 6px;border-radius:calc(10px * var(--dm-rk));text-align:left;width:100%;transition:background .2s,opacity .3s}
@media (hover:hover) and (pointer:fine){.agx-e:hover{background:var(--dm-row)}}
/* the open event needs no fill of its own: it sits on the panel's white and its prep notes show it is open */
.agx-e.open{background:var(--dm-surface)}
@media (hover:hover) and (pointer:fine){.agx-e.open:hover{background:var(--dm-surface)}}
/* a past event: its title steps down to muted and its bar fades, the text stays readable */
.agx-e.past .t b{color:var(--dm-muted)}.agx-e.past .bar{opacity:.5}
.agx-e .tm{font-size:12px;color:var(--dm-muted);padding-top:1px}
.agx-e .bar{border-radius:2px;background:var(--dm-accent-mark,var(--dm-accent))}
.agx-e .t{display:flex;flex-direction:column;font-size:13px;min-width:0}
.agx-e .t b{font-weight:500}
.agx-e .t span{font-size:12px;color:var(--dm-muted)}
.agx-e .who{display:flex;margin-top:6px}
.agx-e .who .av{width:20px;height:20px;font-size:8.5px;color:#fff;margin-right:-2px;box-shadow:0 0 0 1.5px var(--dm-surface)}
.agx-prep{grid-column:3;font-size:12.5px;line-height:1.5;color:var(--dm-fg2);display:flex;flex-direction:column;gap:5px;padding-top:var(--dm-s-2)}
.agx-prep div{display:flex;gap:7px;align-items:flex-start}
.agx-prep svg{color:var(--dm-accent-fg,var(--dm-accent));margin-top:3px;flex:none}
.agx-now{display:flex;align-items:center;gap:6px;margin:2px 0;font-size:11px;color:var(--dm-accent-fg,var(--dm-accent));font-weight:500;padding-left:6px}
.agx-now::after{content:"";flex:1;height:2px;background:var(--dm-accent-mark,var(--dm-accent));border-radius:1px}
.agx-now i{width:7px;height:7px;border-radius:50%;background:var(--dm-accent-mark,var(--dm-accent));animation:agnow 2s ease-in-out infinite}
@keyframes agnow{50%{box-shadow:0 0 0 5px var(--dm-accent-bg)}}
.agx-join{margin-top:var(--dm-s-2);align-self:flex-start}

