});

c65.css:
/* ---------- Health score ---------- */
/* an account's health: the score in a small ring with its verdict, the four factors as rows under one another (each with its
   status dot and its figure, opening its detail right under it) and the agent's next move with its button. The rows are split
   by hairlines, with no fill, shadow or card of their own (owner, 9 Nov). The state shows only in the status dots and the
   ring, and the weakest factor off track gets an ink label */
.hsc{display:flex;flex-direction:column;gap:var(--dm-s-3);width:100%;padding:var(--dm-s-4);container-type:inline-size;--dm-vm:var(--dm-ok-mark);--dm-vf:var(--dm-ok)}
.hsc[data-v="warn"]{--dm-vm:var(--dm-warn-mark);--dm-vf:var(--dm-warn)}
.hsc[data-v="bad"]{--dm-vm:var(--dm-bad-mark);--dm-vf:var(--dm-bad)}
.hsc-sr{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
/* the account it is about, when the block stands on its own (a details sheet that names the account leaves it out) */
.hsc-ac{display:flex;flex-direction:column;align-items:flex-start;padding-bottom:var(--dm-s-3);border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);line-height:1.4}
.hsc-ac b{font-size:14px;font-weight:500}
.hsc-ac>span{font-size:12.5px;color:var(--dm-muted)}
/* the header line: the score in its ring, the verdict and how it moved */
.hsc-h{display:flex;align-items:center;gap:var(--dm-s-3)}
.hsc-ring{position:relative;flex:none;width:44px;height:44px;display:grid;place-items:center}
.hsc-ring svg{position:absolute;inset:0;width:100%;height:100%;transform:rotate(-90deg);overflow:visible}
.hsc-ring circle{fill:none;stroke-width:4}
.hsc-ring .tr{stroke:var(--dm-line)}
.hsc-ring .fl{stroke:var(--dm-vm);stroke-linecap:round;transition:stroke-dashoffset .9s var(--dm-ease),stroke var(--dm-t) var(--dm-ease)}
.hsc-ring b{position:relative;font-size:14px;font-weight:500;letter-spacing:-.01em;line-height:1}
.hsc-ht{flex:1;min-width:0;display:flex;flex-direction:column;align-items:flex-start;line-height:1.4}
.hsc-vd{font-size:14px;font-weight:500;color:var(--dm-vf);transition:color var(--dm-t) var(--dm-ease)}
.hsc-sub{font-size:12.5px;color:var(--dm-muted);text-wrap:pretty}
.hsc-dl{flex:none;align-self:flex-start;margin-top:4px;font-size:12.5px;color:var(--dm-muted)}
/* the factors: a row each, a hairline above every row. A row is its status dot and name (and Weakest), its figure and unit,
   and a chevron; its detail opens right under it */
.hsc-l{display:flex;flex-direction:column}
.hsc-t{display:grid;grid-template-columns:minmax(0,1fr) auto 16px;grid-template-areas:"k v cv";align-items:center;column-gap:var(--dm-s-3);width:100%;min-height:44px;padding:10px 0;border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);text-align:left;--dm-sm:var(--dm-ok-mark)}
.hsc-t[data-s="warn"]{--dm-sm:var(--dm-warn-mark)}
.hsc-t[data-s="bad"]{--dm-sm:var(--dm-bad-mark)}
.hsc-t:focus-visible{outline-offset:-2px;border-radius:var(--dm-r-sm)}
.hsc-k{grid-area:k;display:flex;align-items:center;gap:6px;min-width:0;font-size:13px;line-height:20px;color:var(--dm-fg2);transition:color var(--dm-t-fast)}
.hsc-n{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.hsc-dot{flex:none;width:8px;height:8px;border-radius:50%;background:var(--dm-sm);transition:background var(--dm-t) var(--dm-ease)}
/* the weakest factor that is off track says so in ink, never with a fill */
.hsc-wk{flex:none;display:none;margin-left:2px;font-size:11px;font-weight:500;line-height:16px;color:var(--dm-fg)}
.hsc-t[data-weak] .hsc-wk{display:block}
.hsc-v{grid-area:v;display:flex;align-items:baseline;justify-content:flex-end;gap:5px;white-space:nowrap;line-height:20px}
.hsc-v b{font-size:14px;font-weight:500;letter-spacing:-.01em;color:var(--dm-fg)}
.hsc-v>span{font-size:12px;color:var(--dm-muted)}
.hsc-cv{grid-area:cv;justify-self:end;color:var(--dm-muted);transition:transform var(--dm-t) var(--dm-ease),color var(--dm-t-fast)}
.hsc-t[aria-expanded="true"] .hsc-k{color:var(--dm-fg)}
.hsc-t[aria-expanded="true"] .hsc-cv{transform:rotate(180deg);color:var(--dm-fg2)}
@media (hover:hover) and (pointer:fine){
  .hsc-t:hover .hsc-k{color:var(--dm-fg)}
  .hsc-t:hover .hsc-cv{color:var(--dm-fg2)}
}
/* a row's detail: plain lines under its name, no card */
.hsc-dc{padding:0 0 var(--dm-s-3) 14px}
.hsc-dp{margin:0;font-size:12.5px;line-height:1.5;color:var(--dm-fg);text-wrap:pretty}
.hsc-dp+.hsc-dp{margin-top:2px;color:var(--dm-fg2)}
.hsc-pt{display:flex;align-items:center;gap:var(--dm-s-2);margin:var(--dm-s-2) 0 0;font-size:12px;color:var(--dm-muted)}
.hsc-pt i{width:4px;height:4px;border-radius:50%;background:var(--dm-faint)}
/* the agent's next move: a plain row under a hairline, the spark in the accent, one line and its button */
.hsc-s{display:flex;align-items:center;gap:var(--dm-s-2);min-height:44px;padding-top:var(--dm-s-3);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:12.5px;line-height:1.45;color:var(--dm-fg2)}
.hsc-s>.i{flex:none;align-self:flex-start;margin-top:3px;color:var(--dm-accent-mark,var(--dm-accent))}
.hsc-st{flex:1;min-width:0;text-wrap:pretty}
.hsc-s .pill{flex:none}
.hsc-s .pill .spin{width:12px;height:12px}
.hsc-done{flex:none;outline:0}
.hsc-done .i{margin-left:-1px}
/* Blueprint: square marks, labels in small capitals */
:root:not([data-style="soft"]) :is(.hsc-k,.hsc-pt):not(:where([data-style="soft"],[data-style="soft"] *)){font-size:11px;font-weight:500;letter-spacing:.04em;text-transform:uppercase}
:root:not([data-style="soft"]) .hsc-done:not(:where([data-style="soft"],[data-style="soft"] *)){font-size:11px}
/* a narrow block (a phone, a slim sheet): the button goes under the agent's line */
@container (max-width:359px){
  .hsc-s{flex-wrap:wrap;row-gap:var(--dm-s-2)}
  .hsc-st{flex:1 1 calc(100% - 26px)}
  .hsc-s :is(.pill,.hsc-done){margin-left:22px}
}

c65.js:
/* three accounts on Mon Nov 9. A factor's points add up to the score: contact 30, deals on time 25, win chance 25 and next
   step 20. Each factor has its status (ok, warn, bad), its figure and unit, a line for screen readers (say) and the lines its
   detail shows. The agent's suggestion has its button, what it says once done, and the factors it changes (after) */
const HSC = [
  { n:'Granite Peak Systems', seg:'Strategic, Americas', was:85,
    f:{
      contact:{ s:'ok', fig:'2d', unit:'ago', say:'last touch 2 days ago', pts:28, max:30,
        lines:['Last touch Nov 7, a pricing call with Dana Ruiz.', 'In touch every week for the last 6 weeks.'] },
      late:{ s:'ok', fig:'0', unit:'late', say:'no deal past its close date', pts:25, max:25,
        lines:['3 open deals, none past its close date.', 'Next to close: Platform renewal, Nov 24.'] },
      win:{ s:'ok', fig:'62%', unit:'', say:'62% across the open deals', pts:16, max:25,
        lines:['62% weighted across 3 open deals.', 'Up from 54% six weeks ago.'] },
      next:{ s:'ok', fig:'Thu', unit:'in 3 days', say:'pricing call on Thursday', pts:20, max:20,
        lines:['Pricing call, Thu Nov 12, 9am, with Dana Ruiz.'] }
    },
