/* ---------- Memory panel ---------- */
/* each memory shows where it came from, as that source's own mark (Slack, Figma, GitHub, Notion, Linear, Drive) or an icon
   (something said in chat, an edit), and its kind in the kind's colour (--dm-k). A memory the agent learns arrives shimmering
   while it works the rule out, then sits on the accent's tint with a New tag; the memories an answer uses pulse once and say so */
.mmx{padding:var(--dm-s-3);display:flex;flex-direction:column;gap:var(--dm-s-2);min-height:330px}
/* on a card the panel sits centred in the room kept for its tallest moment, and glides up as a new memory opens its row */
.stage-in:has(>.mmx){display:flex;flex-direction:column;justify-content:center}
.mmx-h{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.mmx-ic{width:32px;height:32px;border-radius:calc(10px * var(--dm-rk));background:var(--dm-pp-bg);color:var(--dm-pp);display:grid;place-items:center;flex:none}
.mmx-ht{display:flex;flex-direction:column;flex:1;min-width:0;font-size:13.5px}
.mmx-ht b{font-weight:500}
.mmx-sub{display:flex;align-items:center;gap:var(--dm-s-2);min-width:0}
.mmx-st{font-size:12px;white-space:nowrap}
/* the apps it has learned from, as a row of their marks */
.mmx-srcs{display:inline-flex;align-items:center;gap:3px}
.mmx-srcs span{width:18px;height:18px;border-radius:5px;display:grid;place-items:center;flex:none;background:var(--dm-surface);color:var(--dm-fg);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-rail) 50%,transparent)}
.mmx-srcs .brand{width:11px;height:11px}
@media (max-width:600px){.mmx-srcs{display:none}}
.mmx-tab button{font-size:12px;height:26px;padding:0 9px}
.mmx-list{display:flex;flex-direction:column}
.mmx-m{display:flex;align-items:flex-start;gap:10px;padding:var(--dm-s-2) 6px;border-radius:calc(10px * var(--dm-rk));font-size:13px;line-height:1.5;transition:background .3s}
@media (hover:hover) and (pointer:fine){.mmx-m:hover{background:var(--dm-row)}}
.mmx-src{width:28px;height:28px;margin-top:1px;border-radius:calc(8px * var(--dm-rk));display:grid;place-items:center;flex:none;background:var(--dm-surface);color:var(--dm-fg2);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-rail) 50%,transparent)}
.mmx-src .brand{width:15px;height:15px;color:var(--dm-fg)}
.mmx-src .spin{width:12px;height:12px}
.mmx-b{flex:1;min-width:0;display:flex;flex-direction:column}
.mmx-m .t{outline:0;border-radius:5px;padding:0 3px;margin:0 -3px}
.mmx-m .t[contenteditable="true"]{background:var(--dm-surface);box-shadow:0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent)}
.mmx-m .t[contenteditable="true"]:focus{box-shadow:0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
/* under it: its kind in the kind's colour, then where it came from */
.mmx-meta{display:flex;align-items:center;gap:6px;min-width:0;font-size:11.5px;color:var(--dm-muted);white-space:nowrap}
.mmx-meta>*{flex:none}
.mmx-meta .k{color:var(--dm-k);font-weight:500}
.mmx-meta .s{flex:0 1 auto;min-width:0;overflow:hidden;text-overflow:ellipsis}
.mmx-meta .tag{height:17px;padding:0 5px;font-size:11px}
.mmx-meta .tag.nw{background:var(--dm-accent-bg);color:var(--dm-accent-fg,var(--dm-fg))}
.mmx-m .acts{display:flex;opacity:0;transition:opacity .2s}
.mmx-m:focus-within .acts{opacity:1}
@media (hover:hover) and (pointer:fine){.mmx-m:hover .acts{opacity:1}}
.mmx-m .ib{width:24px;height:24px}
.mmx-m.learn .acts{visibility:hidden}
.mmx-m.new{background:var(--dm-sel)}
/* a memory an answer uses pulses once with the accent's tint, and its source lifts */
.mmx-m.use{animation:mmxuse 1.4s var(--dm-ease)}
.mmx-m.use .mmx-src{animation:mmxlift .6s var(--dm-ease)}
@keyframes mmxuse{0%{background:color-mix(in srgb,var(--dm-accent) 16%,transparent)}100%{background:transparent}}
@keyframes mmxlift{40%{transform:translateY(-2px) scale(1.08)}}
.mmx-gone{display:flex;align-items:center;justify-content:space-between;gap:var(--dm-s-2);padding:6px var(--dm-s-2);border-radius:calc(10px * var(--dm-rk));font-size:12.5px;color:var(--dm-muted);background:var(--dm-chip)}
.mmx-gone button{color:var(--dm-accent-fg,var(--dm-accent));font-weight:500;font-size:12.5px}
/* the line at the foot: how often the memory is used, or the answer it is helping with now */
.mmx-f{display:flex;align-items:center;gap:var(--dm-s-2);margin-top:auto;padding:10px 6px 2px;border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:12px;color:var(--dm-muted)}
.mmx-fi{display:grid;place-items:center;flex:none;color:var(--dm-fg2)}
.mmx-fi .brand{width:14px;height:14px}
.mmx-ft{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mmx-ft.sw{display:block}
:root:not([data-style="soft"]) .mmx-m.new:not(:where([data-style="soft"],[data-style="soft"] *)){background:repeating-linear-gradient(135deg,transparent 0 5px,color-mix(in srgb,var(--dm-accent-mark) 14%,transparent) 5px 6px),var(--dm-sel)}
:root:not([data-style="soft"]) .mmx-m.use:not(:where([data-style="soft"],[data-style="soft"] *)){animation:mmxusebp .9s steps(3,end)}
