    if (b.dataset.pop){ menuFor = k.id; menuFrom = 'sheet'; checks(k); }
  });
  c.on(sheet, 'keydown', e => { if (e.key === 'Escape' && !menuOpen()){ e.stopPropagation(); closeSheet(true); } });

