/* ---------- Ticket list ---------- */
/* rows run edge to edge inside the panel, so there is one surface instead of nested ones */
/* the panel fits the tickets it lists, however few are left */
.tkx{padding:var(--dm-s-3) 0 0;display:flex;flex-direction:column;gap:6px;overflow:hidden}
.tkx-h{display:flex;align-items:center;justify-content:space-between;padding:0 var(--dm-s-4) var(--dm-s-1);font-size:14px}
.tkx-h b{font-weight:500}
.tkx-sg button{font-size:12px;height:26px;padding:0 9px}
.tkx-list{display:flex;flex-direction:column}
.tkx-t{transition:background .2s;box-shadow:inset 0 1px 0 color-mix(in srgb,var(--dm-line) 50%,transparent)}
@media (hover:hover) and (pointer:fine){.tkx-t:hover{background:var(--dm-row)}}
.tkx-t.open{background:color-mix(in srgb,var(--dm-wash) 50%,var(--dm-surface))}
.tkx-r{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:10px;width:100%;padding:10px var(--dm-s-4);text-align:left}
/* rows fill the card, whose rounded edge would cut an outside ring: theirs is drawn inside */
.tkx-r:focus-visible{outline-offset:-2px}
.tkx-r .pr{display:flex;align-items:center;justify-content:center;width:18px;height:18px}
.tkx-r .pr .dot{width:8px;height:8px}
.tkx-r .t{display:flex;flex-direction:column;min-width:0;font-size:13px}
.tkx-r .t b{font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tkx-r .t span{font-size:12px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tkx-r .m{display:flex;align-items:center;gap:6px}
.tkx-r .m .av{width:20px;height:20px;font-size:9px}
.tkx-r .w{font-size:11.5px;color:var(--dm-muted)}
.tkx-d{padding:0 var(--dm-s-4) 14px 44px;display:flex;flex-direction:column;gap:var(--dm-s-2)}
.tkx-q{font-size:12.5px;line-height:1.5;color:var(--dm-fg2)}
.tkx-s{padding:10px var(--dm-s-3);border-radius:var(--dm-r-in);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:12.5px;line-height:1.5;color:var(--dm-fg)}
.tkx-s .lb{display:flex;align-items:center;gap:6px;font-size:11.5px;color:var(--dm-accent-fg,var(--dm-accent));font-weight:500;margin-bottom:var(--dm-s-1)}
/* the reply reads as text you can edit: the text cursor over it, and an accent caret once it has focus */
.tkx-s [contenteditable]{outline:0;border-radius:calc(6px * var(--dm-rk));cursor:text;caret-color:var(--dm-accent-fg,var(--dm-accent))}
.tkx-s [contenteditable]:focus{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent);padding:2px var(--dm-s-1);margin:-2px -4px}
.tkx-a{display:flex;gap:6px;justify-content:flex-end}
.tkx-e{padding:40px 10px;text-align:center;font-size:13px;color:var(--dm-muted)}
.tkx-t.leave{animation:leave .35s var(--dm-ease) both}

