.tcx-c.open .tcx-chev{transform:rotate(180deg)}
.tcx-io{padding:2px var(--dm-s-2) var(--dm-s-2) 42px;display:grid;gap:var(--dm-s-2)}
.tcx-l{font-size:11.5px;color:var(--dm-muted);margin-bottom:var(--dm-s-1)}
.tcx-io pre{margin:0;padding:9px 11px;border-radius:calc(10px * var(--dm-rk));background:var(--dm-chip);font-family:var(--dm-mono);font-size:11.5px;line-height:1.65;white-space:pre-wrap;word-break:break-word}
.tcx-io .k{color:var(--dm-pb)}.tcx-io .s{color:var(--dm-pm)}.tcx-io .n{color:var(--dm-pp)}

