/* ---------- Artifact card ---------- */
/* a file the agent made, shown four ways: a compact row, a card with its first page, a chip inside the message, and a stack
   of its versions. Each plays its writing state, then opens, copies, downloads and switches versions the same way */
/* the reader opens over the card's nearest positioned ancestor: on this page the stage, in an app its chat column */
.afx{--dm-afx-t2:var(--dm-muted)}
/* the variants share one room, as tall as the tallest moment (the compact card with its versions open), so switching
   never moves what is below and an open menu still sits centred */
.afx.dm>.afx-main{position:relative;min-height:452px;justify-content:center}
@container (max-width:400px){.afx.dm>.afx-main{min-height:474px}}
/* secondary text: the core's grey in light mode; in dark mode a lighter grey, because the core's reaches 4.5:1 there but
   not APCA Lc 60, which small text needs */
:root[data-theme="dark"] .afx{--dm-afx-t2:#c0c0c0}
