.mpk-mk{width:20px;height:20px;border-radius:calc(6px * var(--dm-rk));display:grid;place-items:center;font-size:11px;font-weight:500;color:var(--dm-mt,var(--dm-on-ink));background:var(--dm-mc,var(--dm-fg2));flex:none;transition:background .32s}
