.mpk-o.busy .d{color:var(--dm-warn)}
.mpk-o.busy .mpk-mk{background:var(--dm-warn-mark);color:var(--dm-on-ink)}
.mpk-m{display:flex;gap:2px;height:8px}
.mpk-m i{flex:1;border-radius:2px;background:var(--dm-rail);transition:background .32s}
.mpk-m i.on{background:var(--dm-fg2)}
.mpk-o[aria-checked="true"]:not(.busy) .mpk-m i.on{background:var(--dm-accent-mark,var(--dm-accent))}
/* the way out when a model can't take the request: wait for it, or a close match that starts now */
.mpk-sg{margin:var(--dm-s-1) var(--dm-s-1) 2px;padding:10px var(--dm-s-3);border-radius:var(--dm-r-in);background:var(--dm-warn-bg);display:flex;flex-direction:column;gap:var(--dm-s-2)}
