/* ---------- Draft review ---------- */
/* what the agent wrote, laid out like the email it is: who it goes to, the subject, the message and what is attached,
   then send now or later, or discard. Before sending it checks for an attachment the message mentions, and after
   sending there is a short window to undo */
.drf{position:relative;width:100%;max-width:440px;margin:0 auto;padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-3)}
.drf-h{display:flex;align-items:center;gap:var(--dm-s-3)}
.drf-ag{width:32px;height:32px;border-radius:calc(9px * var(--dm-rk));background:var(--dm-chip);color:var(--dm-fg2);display:grid;place-items:center;flex:none}
.drf-ht{flex:1;min-width:0;display:flex;flex-direction:column}
