/* ---------- Agent tree ---------- */
/* an orchestrator and its sub-agents as a tree: a chevron folds a branch, each row shows its task, status and cost, and a
   branch's cost is its own plus everything under it */
.atr{width:100%;max-width:440px;margin:0 auto;padding:6px}
.atr-h{display:flex;align-items:center;justify-content:space-between;gap:var(--dm-s-3);padding:var(--dm-s-2) 10px 10px}
.atr-ht{display:flex;flex-direction:column;min-width:0}
.atr-ht b{font-weight:500;font-size:14px}
.atr-st{font-size:12.5px}
.atr-tot{font-size:14px;font-weight:500}
.atr-tree{display:flex;flex-direction:column;padding-top:var(--dm-s-1);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.atr-n{display:flex;align-items:center;gap:var(--dm-s-2);min-height:44px;padding:5px 10px 5px calc(4px + var(--dm-lv,0) * 20px);border-radius:calc(10px * var(--dm-rk));font-size:13px;outline:0;transition:background .16s}
@media (hover:hover) and (pointer:fine){.atr-n:hover{background:var(--dm-row)}}
.atr-n:focus-visible{box-shadow:inset 0 0 0 2px var(--dm-focus)}
.atr-tg{width:20px;height:20px;display:grid;place-items:center;flex:none;border-radius:calc(6px * var(--dm-rk));color:var(--dm-muted);transition:background .16s,color .16s}
@media (hover:hover) and (pointer:fine){.atr-tg:hover{background:var(--dm-row);color:var(--dm-fg)}}
.atr-tg svg{transition:transform .32s var(--dm-ease)}
.atr-n[aria-expanded="false"] .atr-tg svg{transform:rotate(-90deg)}
.atr-sp{width:20px;flex:none}
.atr-g{width:16px;height:16px;display:grid;place-items:center;flex:none;color:var(--dm-faint)}
.atr-g .spin{width:11px;height:11px;color:var(--dm-accent-fg,var(--dm-accent))}
.atr-n.done .atr-g{color:var(--dm-ok)}
.atr-n.fail .atr-g{color:var(--dm-bad)}
.atr-t{flex:1;min-width:0;display:flex;flex-direction:column}
.atr-t b{font-weight:500}
.atr-t span{font-size:12px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.atr-n.fail .atr-t span{color:var(--dm-bad)}
.atr-n.queued .atr-t b{color:var(--dm-fg2)}
.atr-c{font-size:12.5px;color:var(--dm-fg2);min-width:44px;text-align:right}
.atr-n.queued .atr-c{color:var(--dm-muted)}
/* the way out of a failed step: a white button on its red-tinted row */
.atr-n.fail{background:var(--dm-bad-bg)}
.atr-fix{flex:none;align-self:flex-start;margin-top:var(--dm-s-1);background:var(--dm-surface);color:var(--dm-fg);box-shadow:var(--dm-shadow)}
@media (hover:hover) and (pointer:fine){.atr-fix:hover{background:var(--dm-surface);box-shadow:var(--dm-shadow-pop)}}
/* a folded branch keeps its children's space shut; the guide line marks the level */
.atr-kids{position:relative}
.atr-kids::before{content:"";position:absolute;top:2px;bottom:6px;left:calc(14px + var(--dm-lv,0) * 20px);width:1px;background:var(--dm-line)}
.atr-sum{display:flex;align-items:center;gap:var(--dm-s-2);margin:var(--dm-s-2) var(--dm-s-1) 2px;padding:10px var(--dm-s-3);border-radius:var(--dm-r-in);background:var(--dm-ok-bg);font-size:13px}
.atr-sum svg{color:var(--dm-ok);flex:none}

