  float w=(.002+.008*L)*(sin(3.*an+t*1.9)+.6*sin(5.*an-t*2.7)+.4*sin(2.*an-t*1.1));
  float rad=.955*(1.+.008*sin(t*.9)+w);
  vec2 q=u/rad;float r=length(q),e=3./(R.y*rad);
