/* ---------- Scheduled runs ---------- */
/* recurring agent tasks: the schedule in words, when it runs next and how its last run went, with Run now and an on/off
   switch. A paused one dims and says so; one whose last run failed says why and offers the fix */
.shx{padding:var(--dm-s-3);display:flex;flex-direction:column;gap:6px}
.shx-h{display:flex;align-items:center;gap:10px;padding:2px 10px var(--dm-s-2)}
.shx-h>div{display:flex;flex-direction:column;min-width:0}
.shx-h b{font-weight:500;font-size:13.5px}
.shx-st{font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.shx-list{display:flex;flex-direction:column}
.shx-r{display:grid;grid-template-columns:28px minmax(0,1fr) auto;align-items:center;column-gap:var(--dm-s-3);padding:var(--dm-s-2) 10px;border-radius:var(--dm-r-in);font-size:13px;transition:background .2s}
@media (hover:hover) and (pointer:fine){.shx-r:hover{background:var(--dm-row)}}
.shx-r .ic{width:28px;height:28px;border-radius:calc(9px * var(--dm-rk));display:grid;place-items:center;position:relative;align-self:center;transition:opacity .3s}
.shx-r .ic.brandic{background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent);color:var(--dm-fg)}
.shx-r .ic .brand{width:15px;height:15px}
.shx-r .ic::after{content:"";position:absolute;right:-2px;bottom:-2px;box-sizing:border-box;width:8px;height:8px;border-radius:50%;background:var(--dm-faint);box-shadow:0 0 0 2px var(--dm-surface);transition:background .3s}
.shx-r[data-st="ok"] .ic::after{background:var(--dm-ok)}
.shx-r[data-st="bad"] .ic::after{background:var(--dm-bad-mark)}
.shx-r[data-st="run"] .ic::after{width:10px;height:10px;right:-3px;bottom:-3px;background:var(--dm-surface);border:1.5px solid var(--dm-accent-mark,var(--dm-accent));border-right-color:transparent;animation:rot .8s linear infinite}
.shx-r.off .ic::after{background:var(--dm-faint)}
/* the name shares its line with Run now and the switch; the schedule and the result below it take the full width */
.shx-r .ic{grid-row:1/4}
.shx-r .t{display:contents}
.shx-r :is(.nm,.d,.res){grid-column:2/-1;transition:color .3s}
.shx-r .nm{grid-column:2}
/* a paused one dims: its tile fades, and its name and result step down to muted, so the text stays readable */
.shx-r.off .ic{opacity:.5}.shx-r.off :is(.nm,.res .i){color:var(--dm-muted)}
.shx-r .nm,.shx-r .d{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.shx-r .d{font-size:12px;color:var(--dm-muted)}
.shx-r .res{display:flex;align-items:center;gap:5px;min-width:0;height:18px;font-size:12px;color:var(--dm-muted)}
.shx-r .res>span{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.shx-r .res .i{color:var(--dm-ok)}
.shx-r[data-st="bad"] .res,.shx-r[data-st="bad"] .res .i{color:var(--dm-bad)}
.shx-act{grid-column:3;grid-row:1;display:flex;align-items:center;gap:var(--dm-s-2);margin-block:-5px}
.shx-run{width:28px;height:28px}
/* the row turns grey under the pointer too, so Run now lifts to a white button with a shadow instead of a grey that would vanish into the row */
@media (hover:hover) and (pointer:fine){.shx-run:hover:not(:disabled){background:var(--dm-surface);color:var(--dm-fg);box-shadow:var(--dm-shadow)}}
.shx-run:disabled{opacity:1;cursor:not-allowed;background:none;color:var(--dm-dis);transform:none}
.shx-r .shx-fx{grid-column:2/-1;grid-row:4}
.shx-fx>div{overflow-clip-margin:0}
.shx-fx>div>div{display:flex;flex-wrap:wrap;gap:6px;padding-top:var(--dm-s-2)}
.shx-add{display:flex;align-items:center;gap:var(--dm-s-2);height:30px;padding:0 var(--dm-s-3) 0 10px;font-size:12.5px;color:var(--dm-fg2);border-radius:var(--dm-r-pill);align-self:flex-start;transition:background-color .2s,color .2s}
@media (hover:hover) and (pointer:fine){.shx-add:hover{color:var(--dm-fg);background:var(--dm-row)}}
.shx-pop{width:272px;padding:var(--dm-s-3)}
.shx-f{display:flex;flex-direction:column;gap:var(--dm-s-2)}
.shx-f h4{margin:0 0 2px;font-size:13px;font-weight:500}
.shx-in{width:100%;height:32px;border:0;outline:0;border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);padding:0 10px;font:inherit;font-size:13px;color:var(--dm-fg);transition:box-shadow var(--dm-t-fast)}
@supports (corner-shape:squircle){.shx-in{corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
.shx-in::placeholder{color:var(--dm-muted)}
.shx-in:focus{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.shx-rep{display:flex}
.shx-rep button{flex:1 1 auto;padding:0 var(--dm-s-2)}
.shx-days{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:var(--dm-s-1)}
.shx-days button{height:28px;border-radius:var(--dm-r-sm);background:var(--dm-chip);font-size:12px;color:var(--dm-fg2);transition:background .2s,color .2s}
@media (hover:hover) and (pointer:fine){.shx-days button:hover{background:var(--dm-hover);color:var(--dm-fg)}}
.shx-days button[aria-pressed="true"]{background:var(--dm-accent-bg);color:var(--dm-accent-fg,var(--dm-accent))}
.shx-ff{display:flex;align-items:center;gap:var(--dm-s-2);padding-top:2px}
.shx-sum{flex:1;min-width:0;font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}

