/* ---------- Segmented control ---------- */
/* one choice from a few views of the same thing: the picked one sits on a white knob that slides to it. It is a tab
   list, so the arrow keys move along it and the panel under it changes with it */
.sgc{width:100%;max-width:400px;margin:0 auto;padding:var(--dm-s-4);display:flex;flex-direction:column;gap:14px}
.sgc-h{display:flex;align-items:center;justify-content:space-between;gap:var(--dm-s-3);flex-wrap:wrap}
.sgc-ht{display:flex;flex-direction:column;min-width:0}
.sgc-ht b{font-weight:500;font-size:14px}
.sgc-bar{display:flex;align-items:center;gap:2px;margin:-4px 0 -6px}
.sgc-r{flex:1;min-width:0;font-size:13px;color:var(--dm-fg2);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.sgc-bar .ib{width:28px;height:28px}
.sgc-bar .pill{margin-right:var(--dm-s-1)}
.sgc-seg{position:relative;display:inline-flex;padding:3px;border-radius:var(--dm-r-pill);background:var(--dm-chip);flex:none}
.sgc-k{position:absolute;top:3px;bottom:3px;left:3px;width:0;border-radius:var(--dm-r-pill);background:var(--dm-raised);box-shadow:var(--dm-seg-k-shadow,var(--dm-shadow));transition:left .42s var(--dm-ease),width .42s var(--dm-ease)}
.sgc-seg button{position:relative;z-index:1;height:30px;padding:0 14px;border-radius:var(--dm-r-pill);font-size:13px;color:var(--dm-fg2);outline:0;transition:color .2s}
.sgc-seg button[aria-selected="true"],.sgc-seg button[aria-checked="true"]{color:var(--dm-fg)}
@media (hover:hover) and (pointer:fine){.sgc-seg button:hover{color:var(--dm-fg)}}
.sgc-seg button:focus-visible{box-shadow:0 0 0 2px var(--dm-focus)}
.sgc-p{position:relative;height:178px;border-radius:var(--dm-r-in);outline:0}
.sgc-p:focus-visible{box-shadow:0 0 0 2px var(--dm-focus)}
.sgc-in{height:100%}
/* a new view crossfades over the one it replaces, so the panel is never empty between them */
.sgc-in.fresh{animation:sgcin .24s var(--dm-ease) both}
.sgc-in.gone{position:absolute;inset:0;pointer-events:none;animation:sgcout .24s var(--dm-ease) both}
@keyframes sgcin{from{opacity:0;transform:translateY(4px)}}
@keyframes sgcout{to{opacity:0}}
/* the day: its events in order */
.sgc-day{display:flex;flex-direction:column;gap:6px}
.sgc-ev{display:flex;align-items:center;gap:var(--dm-s-3);min-height:50px;padding:6px var(--dm-s-3);border-radius:var(--dm-r-in);background:var(--dm-row);font-size:13px}
