.sgc-ev .t span{font-size:12px;color:var(--dm-muted)}
.sgc-none{height:100%;display:grid;place-items:center;font-size:13px;color:var(--dm-muted)}
/* the week: the five working days, one roomy row each with its first event, a count of the rest, and today picked out */
.sgc-wk{display:flex;flex-direction:column;gap:var(--dm-s-1)}
.sgc-wr{display:flex;align-items:center;gap:var(--dm-s-3);width:100%;height:32px;padding:0 var(--dm-s-3);border-radius:var(--dm-r-sm);font-size:13px;text-align:left;transition:background var(--dm-t-fast)}
