.sgc-wr .d{width:52px;flex:none;color:var(--dm-muted)}
.sgc-wr .e{flex:1;min-width:0;display:flex;align-items:center;gap:var(--dm-s-2);white-space:nowrap}
.sgc-wr .e i{width:6px;height:6px;border-radius:50%;background:var(--dm-c);flex:none}
