@media (hover:hover) and (pointer:fine){.sgc-mo .d:hover{background:var(--dm-row)}}
.sgc-mo .d.on{background:var(--dm-surface);color:var(--dm-fg);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-pick-on) 50%,transparent)}
.sgc-mo .d.e::after{content:"";position:absolute;bottom:2px;left:50%;width:4px;height:4px;margin-left:-2px;border-radius:50%;background:var(--dm-accent-mark,var(--dm-accent))}
.sgc-mo .d.now{background:var(--dm-ink);color:var(--dm-on-ink)}
@media (hover:hover) and (pointer:fine){.sgc-mo .d.now:hover{background:var(--dm-ink);color:var(--dm-on-ink)}}
.sgc-mo .d.now::after{background:var(--dm-on-ink)}

