/* ---------- Hand-off to a person ---------- */
/* the agent passes a conversation to a person: why, who has it (with Reassign), when the reply is due, what they need to
   pick it up, and what the customer was told. The type and spacing are Draft review's; the two columns stack when narrow */
.hox{position:relative;width:100%;margin:0 auto;padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-3)}
.hox-h{display:flex;align-items:center;gap:var(--dm-s-3)}
.hox-ic{width:32px;height:32px;border-radius:calc(9px * var(--dm-rk));background:var(--dm-chip);color:var(--dm-fg2);display:grid;place-items:center;flex:none}
.hox-ht{flex:1;min-width:0;display:flex;flex-direction:column}
.hox-ht b{font-weight:500;font-size:14px}
.hox-ht span{font-size:13px}
.hox-b{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:var(--dm-s-4) var(--dm-s-6);align-items:start;padding-top:var(--dm-s-3);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
@container (max-width:600px){.hox-b{grid-template-columns:minmax(0,1fr)}.hox-col+.hox-col{padding-top:var(--dm-s-3);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}}
.hox-col{display:flex;flex-direction:column;gap:var(--dm-s-2);min-width:0}
.hox-lb{font-size:12px;color:var(--dm-muted)}
.hox-who{display:flex;align-items:center;gap:10px;min-height:40px}
.hox-av{width:28px;height:28px;display:grid;place-items:center;flex:none;border-radius:50%;background:var(--dm-chip);color:var(--dm-fg2)}
.hox-av .av{width:28px;height:28px;font-size:11px}
.hox-wt{flex:1;min-width:0;display:flex;flex-direction:column}
.hox-wt b{font-weight:500;font-size:13.5px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.hox-wd{display:flex;align-items:center;gap:6px;font-size:12px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.hox-wd .dot{color:var(--dm-faint)}
/* the person's status: the dot is a mark (--dm-ok-mark, --dm-warn-mark) and the words keep the text colours */
.hox-wd.ok .dot{color:var(--dm-ok-mark)}
.hox-wd.warn{color:var(--dm-warn)}
.hox-wd.warn .dot{color:var(--dm-warn-mark)}
/* Reassign: a small dropdown, like the one for how long in Permission gate */
.hox-rb{display:inline-flex;align-items:center;gap:6px;height:28px;padding:0 var(--dm-s-2) 0 10px;border-radius:var(--dm-r-pill);font-size:13px;color:var(--dm-fg2);flex:none;transition:background .16s,color .16s}
.hox-rb[aria-expanded="true"]{background:var(--dm-row);color:var(--dm-fg)}
@media (hover:hover) and (pointer:fine){.hox-rb:hover{background:var(--dm-row);color:var(--dm-fg)}}
.hox-rb>svg{color:var(--dm-muted);transition:transform .32s var(--dm-ease)}
.hox-rb[aria-expanded="true"]>svg{transform:rotate(180deg)}
.hox-rb[disabled]{opacity:1;cursor:not-allowed;background:none;color:var(--dm-dis)}
.hox-pop{min-width:240px}
.hox-pop .mi .av{width:20px;height:20px;font-size:9px}
.hox-pop .mi>span:not(.ck):not(.av){flex:1;min-width:0}
/* when the reply is due: the line counts down and the bar empties, amber in the last five minutes */
.hox-sla{display:flex;flex-direction:column;gap:var(--dm-s-2);padding-top:var(--dm-s-2)}
.hox-sl{display:flex;align-items:center;gap:var(--dm-s-2);font-size:13px}
.hox-sl>svg{color:var(--dm-fg2);flex:none}
.hox-sl .muted{margin-left:auto;font-size:12px;white-space:nowrap}
.hox-due{min-width:0}
.hox-bar{height:4px;border-radius:2px;background:var(--dm-chip);overflow:hidden}
.hox-bar i{display:block;height:100%;width:100%;border-radius:inherit;background:var(--dm-fg2);transition:width 1s linear,background .3s}
.hox-sla.warn .hox-sl>svg,.hox-sla.warn .hox-due{color:var(--dm-warn)}
.hox-sla.warn .hox-bar i{background:var(--dm-warn-mark)}
.hox-sla.bad .hox-sl>svg,.hox-sla.bad .hox-due{color:var(--dm-bad)}
.hox-sum{margin:0;font-size:13px;line-height:1.5;color:var(--dm-fg2)}
.hox-facts{display:flex;flex-direction:column;border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.hox-f{display:flex;align-items:center;gap:10px;min-height:32px;border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:13px}
.hox-f .k{width:72px;flex:none;color:var(--dm-muted)}
.hox-f .v{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.hox-lnk{align-self:flex-start;max-width:100%}
.hox-lnk>span{overflow:hidden;text-overflow:ellipsis}
/* what the customer was told, editable in place */
.hox-ms{display:flex;flex-direction:column;gap:var(--dm-s-2);margin-top:var(--dm-s-1);padding-top:var(--dm-s-3);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.hox-mh{display:flex;align-items:center;gap:var(--dm-s-2);min-height:28px}
.hox-mh .sp{flex:1}
.hox-mb{padding:10px var(--dm-s-3);border-radius:var(--dm-r-in);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:13.5px;line-height:1.5;outline:0;transition:box-shadow var(--dm-t-fast),background var(--dm-t-fast)}
.hox-mb[contenteditable="true"]{background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent)}
@supports (corner-shape:squircle){.hox-mb[contenteditable="true"]{corner-shape:squircle;border-radius:var(--dm-r-box-sq)}}
.hox-mb[contenteditable="true"]:focus{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
/* where it stands, in one row at the foot: neutral while it waits, amber when the person can't take it, green once they have */
.hox-st{display:flex;align-items:center;gap:var(--dm-s-3);padding:10px 10px 10px var(--dm-s-3);border-radius:var(--dm-r-in);background:var(--dm-chip);font-size:13.5px;transition:background .32s}
.hox-st.warn{background:var(--dm-warn-bg)}
.hox-st.ok{background:var(--dm-ok-bg)}
.hox-st .g{width:18px;height:18px;display:grid;place-items:center;flex:none;color:var(--dm-fg2)}
.hox-st.warn .g{color:var(--dm-warn)}
.hox-st.ok .g{color:var(--dm-ok)}
.hox-st .g .av{width:18px;height:18px;font-size:8.5px}
.hox-st .t{flex:1;min-width:0;display:flex;flex-direction:column}
.hox-st .t b{font-weight:400}
/* the second line sits on the row's tint, so it is fg2 rather than muted */
.hox-st .t>span{font-size:13px;color:var(--dm-fg2)}
.hox-st .t,.hox-sum,.hox-mb,.tmx-note>span{text-wrap:pretty}

