    await s.beat(3);
    await s.tap(stops[2]); await s.beat(4);
    await s.point(rec); await s.beat(3);
    await s.tap(rec); await s.beat(4);
    await s.tap($('button[data-v="20"]', ticks)); await s.beat(3);
    await s.point(co.knobs[1], false); await s.beat(1);
    co.glide(1, .35); await s.beat(3);
    s.away(); await s.beat(2);
  });
});

c158.css:
/* ---------- Colour picker ---------- */
/* a field for saturation and brightness, rails for hue and opacity, the hex, swatches, and the colour's contrast with white
   and ink text in words; the agent can glide it to a shade that passes or make a 50 to 900 scale from it */
.cpk{padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-3);--dm-h:210;--dm-hc:hsl(210 100% 50%);--dm-c:#2f8cff}
.cpk-sv{position:relative;height:132px;border-radius:var(--dm-r-in);background:linear-gradient(to top,#000,transparent),linear-gradient(to right,#fff,var(--dm-hc));touch-action:none;cursor:crosshair;box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent)}
.cpk-rail{position:relative;height:12px;margin:0 8px;border-radius:calc(6px * var(--dm-rk));touch-action:none;cursor:pointer}
.cpk-hue{background:linear-gradient(to right,#f00,#ff0 17%,#0f0 33%,#0ff 50%,#00f 67%,#f0f 83%,#f00)}
.cpk-al{background:repeating-conic-gradient(#e6e6e6 0 25%,#fff 0 50%) 0 0/8px 8px}
.cpk-al i{position:absolute;inset:0;border-radius:inherit;background:linear-gradient(to right,transparent,var(--dm-c))}
/* the knobs: white rings that show the colour under them */
.cpk-k{position:absolute;left:0;top:0;width:16px;height:16px;margin:-8px 0 0 -8px;border-radius:50%;box-shadow:0 0 0 2px #fff,0 0 0 3px rgba(0,0,0,.18),0 1px 3px rgba(0,0,0,.25);cursor:grab;z-index:1}
.cpk-rail .cpk-k{top:50%}
.cpk-k:focus-visible{outline-offset:4px;border-radius:50%}
.cpk-row{display:flex;align-items:center;gap:var(--dm-s-2)}
.cpk-pv{position:relative;width:32px;height:32px;flex:none;border-radius:var(--dm-r-field);overflow:hidden;background:repeating-conic-gradient(#e6e6e6 0 25%,#fff 0 50%) 0 0/8px 8px;box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent)}
.cpk-pv i{position:absolute;inset:0;background:var(--dm-c)}
.cpk-hx{flex:1;min-width:0;display:flex;align-items:center;gap:2px;height:32px;padding:0 10px;border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);font-size:13px;cursor:text;transition:box-shadow var(--dm-t-fast)}
.cpk-hx:focus-within{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.cpk-hx[aria-invalid="true"]{box-shadow:inset 0 0 0 1px var(--dm-bad)}
.cpk-hx input{flex:1;min-width:0;border:0;outline:0;padding:0;background:none;font:inherit;color:var(--dm-fg);text-transform:uppercase;letter-spacing:.02em}
@supports (corner-shape:squircle){.cpk-hx,.cpk-pv{border-radius:var(--dm-r-field-sq)}}
.cpk-a{font-size:12.5px;min-width:36px;text-align:right}
.cpk-sw{display:flex;gap:6px;flex-wrap:wrap}
.cpk-sw button{width:24px;height:24px;border-radius:calc(7px * var(--dm-rk));background:var(--dm-s);box-shadow:inset 0 0 0 1px rgba(0,0,0,.08);transition:transform .15s var(--dm-ease),box-shadow var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.cpk-sw button:hover{transform:scale(1.08)}}
.cpk-sw button[aria-pressed="true"]{box-shadow:0 0 0 2px var(--dm-surface),0 0 0 3px color-mix(in srgb,var(--dm-pick-on) 70%,transparent)}
.cpk-cr{display:flex;flex-direction:column;gap:2px}
.cpk-ln{display:flex;align-items:center;gap:var(--dm-s-2);font-size:12.5px;color:var(--dm-fg2);padding:2px 0}
.cpk-aa{width:30px;height:22px;flex:none;display:grid;place-items:center;border-radius:calc(6px * var(--dm-rk));background:var(--dm-c);font-size:12px;font-weight:500;box-shadow:inset 0 0 0 1px rgba(0,0,0,.06)}
.cpk-ln .t{flex:1}
.cpk-ln .r{color:var(--dm-fg)}
.cpk-ln .tag{min-width:40px;justify-content:center}
.cpk-act{display:flex;gap:6px;flex-wrap:wrap}
/* the suggestion is an accent highlight, the accent's tint with accent text, like an event in Event calendar (owner, 4 Nov) */
.cpk-fix:not(:disabled){background:var(--dm-accent-bg);color:var(--dm-accent-fg,var(--dm-accent));box-shadow:none}
@media (hover:hover) and (pointer:fine){.cpk-fix:not(:disabled):hover{background:color-mix(in srgb,var(--dm-accent) 16%,transparent)}}
.cpk-sc{display:grid;grid-template-columns:repeat(10,minmax(0,1fr));gap:2px;min-height:38px}
.cpk-sc button{display:flex;flex-direction:column;align-items:center;gap:3px;font-size:10.5px;color:var(--dm-muted);min-width:0}
.cpk-sc button i{display:block;width:100%;height:22px;border-radius:calc(4px * var(--dm-rk));box-shadow:inset 0 0 0 1px rgba(0,0,0,.06)}
.cpk-sc button:first-child i{border-radius:calc(7px * var(--dm-rk)) calc(4px * var(--dm-rk)) calc(4px * var(--dm-rk)) calc(7px * var(--dm-rk))}
.cpk-sc button:last-child i{border-radius:calc(4px * var(--dm-rk)) calc(7px * var(--dm-rk)) calc(7px * var(--dm-rk)) calc(4px * var(--dm-rk))}
.cpk-sc button.base span{color:var(--dm-fg);font-weight:500}
.cpk-sc:empty{background:repeating-linear-gradient(90deg,var(--dm-chip) 0 calc(10% - 2px),transparent calc(10% - 2px) 10%) 0 0/100% 22px no-repeat}
.cpk-sr{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}

