/* ---------- Cost vs quality ---------- */
/* runs as dots: cost along, eval score up, size for tokens, a colour and a shape for each model. Dashed median lines cut the
   chart into four named quadrants; a drag draws a box that selects the runs in it */
.cvq{padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-3)}
.cvq-h{display:flex;align-items:flex-start;justify-content:space-between;gap:10px;flex-wrap:wrap}
.cvq-t{display:flex;flex-direction:column;font-size:13.5px;line-height:1.4}
.cvq-t b{font-weight:500}
.cvq-t .muted{font-size:12px}
.cvq-lg{display:flex;gap:2px}
.cvq-k{display:flex;align-items:center;gap:6px;height:26px;padding:0 8px;border-radius:var(--dm-r-pill);font-size:12px;color:var(--dm-muted);transition:color .2s,background .2s}
@media (hover:hover) and (pointer:fine){.cvq-k:hover{background:var(--dm-row)}}
.cvq-k[aria-pressed="true"]{color:var(--dm-fg)}
.cvq-k svg{width:10px;height:10px;overflow:visible;transition:opacity .3s,transform .3s var(--dm-ease)}
.cvq-k[aria-pressed="false"] svg{opacity:.3;transform:scale(.7)}
.cvq-pl{position:relative;height:244px;touch-action:pan-y;cursor:crosshair;user-select:none;-webkit-user-select:none;border-radius:var(--dm-r-sm)}
.cvq-pl:focus-visible{outline-offset:4px}
.cvq-svg{position:absolute;inset:0;width:100%;height:100%;overflow:visible}
.cvq-svg .gl{stroke:color-mix(in srgb,var(--dm-line) 40%,transparent);stroke-width:1}
.cvq-svg .ax{stroke:color-mix(in srgb,var(--dm-line) 80%,transparent);stroke-width:1}
.cvq-svg .md{stroke:color-mix(in srgb,var(--dm-faint) 75%,transparent);stroke-width:1;stroke-dasharray:3 3}
.cvq-svg text{font-size:10.5px;fill:var(--dm-muted);font-family:var(--dm-sans)}
.cvq-svg text.q{font-size:10px}
.cvq-svg text.at{font-size:10.5px}
.cvq-svg .d{stroke:var(--dm-surface);stroke-width:1;fill-opacity:.85;transition:opacity .25s,fill-opacity .25s}
.cvq-svg .d.dim{opacity:.18}
.cvq-svg .d.off{opacity:0}
.cvq-svg .d.sel{fill-opacity:1;stroke:var(--dm-fg);stroke-width:1.2}
.cvq-svg .d.on{fill-opacity:1;stroke:var(--dm-fg);stroke-width:1.5}
.cvq-svg .ring{fill:none;stroke:var(--dm-fg2);stroke-width:1.2;stroke-dasharray:3 2.5}
.cvq-svg .box{fill:color-mix(in srgb,var(--dm-fg) 5%,transparent);stroke:var(--dm-fg2);stroke-width:1;stroke-dasharray:4 3}
.cvq-tt{position:absolute;left:0;top:0;padding:6px 9px;border-radius:calc(10px * var(--dm-rk));background:var(--dm-ink);color:var(--dm-on-ink);font-size:11.5px;display:flex;flex-direction:column;opacity:0;transform:translate(-50%,-100%) translateY(-6px);transition:opacity .15s;pointer-events:none;white-space:nowrap;z-index:2}
.cvq-tt span{opacity:.75}
.cvq-tt.on{opacity:1}
.cvq-ft{min-height:72px;display:flex;align-items:center;gap:var(--dm-s-2);padding:var(--dm-s-2) var(--dm-s-3);border-radius:var(--dm-r-in);background:var(--dm-row);font-size:12.5px;color:var(--dm-fg2)}
.cvq-msg{flex:1;min-width:0;display:flex;align-items:center;gap:var(--dm-s-2)}
.cvq-msg .i{flex:none;color:var(--dm-accent-fg,var(--dm-accent))}
.cvq-msg b{font-weight:500;color:var(--dm-fg)}
.cvq-ft .pill{flex:none}
.cvq-ft .ib{flex:none;width:26px;height:26px}
.cvq-ft{flex-wrap:wrap}.cvq-msg{flex:1 1 180px}
/* phones and narrow cards: the plot is a little shorter, and a selection's words sit above its action, which takes the full width */
.cvq{container-type:inline-size}
@container (max-width:340px){
  .cvq-pl{height:228px}
  .cvq-ft{flex-direction:column;align-items:stretch;justify-content:center;gap:10px}
  .cvq-msg{flex:none}
  .cvq-msg:has(>.pill){flex-direction:column;align-items:stretch;gap:10px}
  .cvq-ft .pill{justify-content:center}
}

