    sel = R.map((p, i) => i).filter(i => R[i].x >= .03 && R[i].x <= .2 && R[i].y >= 88 && R[i].y <= 97); selected(); await s.beat(3);
    await s.tap($('.cvq-ask', ft)); s.away(); await s.beat(10);
  });
});

c160.css:
/* ---------- Agent phases ---------- */
/* which phase the agent is in, in one line: its glyph, its name shimmering while it lasts, and the time; a track of six short
   segments under it fills phase by phase. When it needs you, is slow or fails, a line under the track says so with what to do;
   once done the line reads how long it took and opens to the phases */
.aph{width:100%;max-width:420px;margin-inline:auto;display:flex;flex-direction:column;gap:var(--dm-s-2);font-size:14px}
.aph-h{display:flex;align-items:center;gap:10px;width:calc(100% + 16px);margin:0 -8px;padding:6px var(--dm-s-2);border-radius:calc(10px * var(--dm-rk));text-align:left;transition:background var(--dm-t-fast)}
.aph-h[aria-disabled="true"]{cursor:default}
@media (hover:hover) and (pointer:fine){.aph-h:not([aria-disabled="true"]):hover{background:var(--dm-row)}}
.aph-g{width:18px;height:18px;flex:none;display:grid;place-items:center;color:var(--dm-accent-fg,var(--dm-accent))}
.aph[data-p="wait"] .aph-g{color:var(--dm-warn-mark)}
.aph[data-p="err"] .aph-g{color:var(--dm-bad)}
.aph[data-p="done"] .aph-g{color:var(--dm-ok)}
.aph-l{flex:1;min-width:0;color:var(--dm-fg)}
.aph-t{font-size:13px;color:var(--dm-muted)}
.aph-chev{color:var(--dm-muted);visibility:hidden;transition:transform .32s var(--dm-ease)}
.aph[data-p="done"] .aph-chev{visibility:visible}
.aph-h[aria-expanded="false"] .aph-chev{transform:rotate(-90deg)}
.aph-tr{display:flex;gap:3px;height:3px}
.aph-tr i{flex:1;border-radius:2px;background:var(--dm-line);position:relative;overflow:hidden}
.aph-tr i b{position:absolute;inset:0;border-radius:inherit;background:var(--dm-accent-mark,var(--dm-accent));transform-origin:left;animation:aphfill .5s var(--dm-ease) backwards}
.aph-tr i.now b{background:color-mix(in srgb,var(--dm-accent-mark,var(--dm-accent)) 45%,var(--dm-line));animation:aphbreathe 1.6s var(--dm-ease-io) infinite}
.aph[data-p="wait"] .aph-tr i.now b{background:var(--dm-warn-mark);animation:none}
.aph[data-p="err"] .aph-tr i.now b{background:var(--dm-bad-mark);animation:none}
.aph[data-p="done"] .aph-tr i b{background:var(--dm-ok)}
@keyframes aphfill{from{transform:scaleX(0)}}
@keyframes aphbreathe{50%{opacity:.45}}
.aph-x{min-height:40px;display:flex;align-items:center}
.aph-n{display:flex;align-items:center;gap:var(--dm-s-2);width:100%;font-size:13px;color:var(--dm-fg2)}
.aph-n>span{flex:1;min-width:0}
.aph-n.ask{padding:6px 6px 6px var(--dm-s-3);border-radius:var(--dm-r-in);background:var(--dm-row);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent);color:var(--dm-fg)}
.aph-n.err{color:var(--dm-bad)}
.aph-n .pill{flex:none}
.aph-list{list-style:none;margin:0;padding:0 0 var(--dm-s-1);display:flex;flex-direction:column;gap:2px}
.aph-list li{display:flex;align-items:center;gap:10px;padding:4px 0;font-size:13px;color:var(--dm-fg2)}
.aph-list li .i{color:var(--dm-ok)}
.aph-list li span:nth-child(2){flex:1}
.aph-list li .num{color:var(--dm-muted);font-size:12px}
.aph-sr{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
@media (prefers-reduced-motion:reduce){.aph-tr i.now b{animation:none}.aph .think.on{animation:none}.aph .think.on i{animation:none}}
:root:not([data-style="soft"]) .aph-tr i:not(:where([data-style="soft"],[data-style="soft"] *)){height:3px}

