/* ---------- Step inspector ---------- */
/* the settings of one step in an agent workflow. Its tile says its kind in colour (the trigger orange, AI steps violet,
   tools teal, app steps and outputs blue, a branch yellow, a wait pink, an approval green), then its name, where it sits
   and Test and More. Under it, sections that fold: what the step does, the data it reads, what it hands on and what happens
   if it fails. Data mapped from an earlier step is a token, the step and then its field; data that no earlier step gives is
   a red token with a line saying why. Data types are coloured chips; every line and edge is grey */
.sti{width:100%;max-width:360px;margin-inline:auto;padding:var(--dm-s-3) var(--dm-s-4) var(--dm-s-1);display:flex;flex-direction:column;text-align:left}
.sti-ti{width:18px;height:18px;flex:none;display:grid;place-items:center;border-radius:calc(5px * var(--dm-rk));background:var(--dm-sti-kb,var(--dm-chip));color:var(--dm-sti-kf,var(--dm-fg2))}
.sti-ti .i{width:11px;height:11px}
.sti-ti[data-k="trigger"]{--dm-sti-kb:var(--dm-pp-bg);--dm-sti-kf:var(--dm-pp)}
.sti-ti[data-k="ai"]{--dm-sti-kb:var(--dm-pl-bg);--dm-sti-kf:var(--dm-pl)}
.sti-ti[data-k="tool"]{--dm-sti-kb:var(--dm-pt-bg);--dm-sti-kf:var(--dm-pt)}
.sti-ti:is([data-k="app"],[data-k="output"]){--dm-sti-kb:var(--dm-pb-bg);--dm-sti-kf:var(--dm-pb)}
.sti-ti[data-k="branch"]{--dm-sti-kb:var(--dm-py-bg);--dm-sti-kf:var(--dm-py)}
.sti-ti[data-k="wait"]{--dm-sti-kb:var(--dm-pk-bg);--dm-sti-kf:var(--dm-pk)}
.sti-ti[data-k="approval"]{--dm-sti-kb:var(--dm-pm-bg);--dm-sti-kf:var(--dm-pm)}
.sti-h{display:flex;align-items:center;gap:10px;padding:2px 0 var(--dm-s-3);border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.sti-h>.sti-ti{width:32px;height:32px;border-radius:calc(9px * var(--dm-rk))}
.sti-h>.sti-ti .i{width:14px;height:14px}
.sti-tx{flex:1;min-width:0;display:flex;flex-direction:column;gap:1px}
.sti-nr{display:flex;align-items:center;gap:6px;min-width:0}
.sti-n{flex:1;min-width:0;width:100%;height:24px;padding:0 6px;margin-left:-6px;border:0;outline:0;border-radius:var(--dm-r-xs);background:none;font:inherit;font-size:14px;font-weight:500;color:var(--dm-fg);text-overflow:ellipsis;box-shadow:inset 0 0 0 1px transparent;transition:box-shadow var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.sti-n:hover{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent)}}
.sti-n:focus{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.sti-kd{display:block;min-width:0;font-size:12px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.sti-kd.ok{color:var(--dm-ok)}
.sti-h .ib{width:28px;height:28px;flex:none;color:var(--dm-muted)}
@media (hover:hover) and (pointer:fine){.sti-h .ib:hover{color:var(--dm-fg)}}
.sti-test.busy .i{animation:rot 1s linear infinite}
/* a section: its head folds it, and says what needs a look */
.sti-sec{border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.sti-sec:last-child{border-bottom:0}
.sti-sh{display:flex;align-items:center;gap:6px;width:100%;min-height:40px;font-size:12.5px;font-weight:500;color:var(--dm-fg);text-align:left}
.sti-sh>.i{color:var(--dm-muted);transform:rotate(90deg);transition:transform var(--dm-t) var(--dm-ease)}
.sti-sh[aria-expanded="false"]>.i{transform:none}
.sti-sh .n{margin-left:auto;font-size:12px;font-weight:400;color:var(--dm-muted)}
.sti-sh .tag{margin-left:auto}
.sti-rows{display:flex;flex-direction:column;gap:2px;padding:0 0 var(--dm-s-3)}
.sti-row{display:grid;grid-template-columns:92px minmax(0,1fr);align-items:center;gap:var(--dm-s-2);min-height:34px}
.sti-row.top{align-items:start}
.sti-row.top>.k{padding-top:7px}
.sti-row>.k{min-width:0;font-size:12.5px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.sti-row>.v{min-width:0;display:flex;align-items:center;flex-wrap:wrap;gap:6px}
/* a choice: a field-like trigger that opens a menu */
.sti-sel{display:inline-flex;align-items:center;gap:6px;max-width:100%;min-width:0;height:30px;padding:0 var(--dm-s-2) 0 10px;border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);font-size:13px;color:var(--dm-fg);text-align:left;transition:box-shadow var(--dm-t-fast),background var(--dm-t-fast)}
@supports (corner-shape:squircle){.sti-sel{corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
.sti-sel>span{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.sti-sel>.i{color:var(--dm-muted)}
@media (hover:hover) and (pointer:fine){.sti-sel:hover{background:var(--dm-row)}}
.sti-sel[aria-expanded="true"]{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
/* a mapped field: the step's tile, the step and the field */
.sti-tok{display:inline-flex;align-items:center;gap:5px;max-width:100%;min-width:0;height:24px;padding:0 var(--dm-s-2) 0 3px;border-radius:var(--dm-r-sm);background:var(--dm-chip);font-size:12px;line-height:24px;color:var(--dm-fg);white-space:nowrap;vertical-align:middle;user-select:none}
.sti-tok .s{min-width:0;max-width:112px;color:var(--dm-muted);overflow:hidden;text-overflow:ellipsis}
.sti-tok .sep{color:var(--dm-muted)}
.sti-tok .f{flex:none;max-width:100%;font-weight:500;overflow:hidden;text-overflow:ellipsis}
.sti-tok.bad{padding-left:6px;background:var(--dm-bad-bg);color:var(--dm-bad)}
.sti-tok.bad .s,.sti-tok.bad .sep{color:inherit}
.sti-tok.none{padding-left:var(--dm-s-2);background:none;box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 60%,transparent);color:var(--dm-muted)}
.sti-tokb{display:inline-flex;max-width:100%;min-width:0;border-radius:var(--dm-r-sm);transition:box-shadow var(--dm-t-fast)}
.sti-tokb .sti-tok{transition:box-shadow var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.sti-tokb:hover .sti-tok{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 60%,transparent)}}
.sti-tokb[aria-expanded="true"] .sti-tok{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.sti-note{grid-column:2;margin:-2px 0 2px;font-size:12px;line-height:1.4;color:var(--dm-bad)}
/* the instructions: text with mapped fields inline */
.sti-ih{display:flex;align-items:center;justify-content:space-between;min-height:30px}
.sti-ih .k{font-size:12.5px;color:var(--dm-muted)}
.sti-ih .pill{margin-right:-8px;color:var(--dm-fg2)}
.sti-ins{display:block;min-height:96px;padding:var(--dm-s-2) 10px;border-radius:var(--dm-r-box);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);font-size:13px;line-height:26px;color:var(--dm-fg);white-space:pre-wrap;overflow-wrap:anywhere;outline:0;cursor:text;transition:box-shadow var(--dm-t-fast)}
@supports (corner-shape:squircle){.sti-ins{corner-shape:squircle;border-radius:var(--dm-r-box-sq)}}
.sti-ins:focus{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.sti-ins .sti-tok{margin:0 1px;cursor:default}
.sti-ins .sti-tok.new{animation:popin .5s var(--dm-ease) backwards}
.sti-insw{display:flex;flex-direction:column;gap:6px;padding:0 0 var(--dm-s-2)}
/* tools and people as chips, each with its remove */
.sti-chips{display:flex;flex-wrap:wrap;align-items:center;gap:6px;padding:5px 0}
.sti-chip{display:inline-flex;align-items:center;gap:5px;height:26px;max-width:100%;padding:0 3px 0 4px;border-radius:var(--dm-r-sm);background:var(--dm-chip);font-size:12.5px;color:var(--dm-fg)}
.sti-chip>span:not(.sti-ti):not(.av){min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.sti-chip .av{width:18px;height:18px;font-size:8.5px}
.sti-chip.new{animation:popin .5s var(--dm-ease) backwards}
.sti-cx{width:20px;height:20px;flex:none;display:grid;place-items:center;border-radius:calc(5px * var(--dm-rk));color:var(--dm-muted);transition:background var(--dm-t-fast),color var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.sti-cx:hover{background:var(--dm-surface);color:var(--dm-fg)}}
.sti-add{width:26px;height:26px;flex:none;display:grid;place-items:center;border-radius:var(--dm-r-sm);color:var(--dm-muted);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 60%,transparent);transition:background var(--dm-t-fast),color var(--dm-t-fast)}
.sti-add[aria-expanded="true"]{background:var(--dm-row);color:var(--dm-fg)}
@media (hover:hover) and (pointer:fine){.sti-add:hover{background:var(--dm-row);color:var(--dm-fg)}}
/* what the step hands on: each field with its type in colour */
.sti-out{display:grid;grid-template-columns:auto auto minmax(0,1fr);align-items:center;gap:var(--dm-s-2);min-height:30px;font-size:13px}
.sti-out .ex{min-width:0;text-align:right;font-size:12px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.sti-out .tag,.sti-dp .tag{font-weight:500}
/* a stepper, a two-way switch and a number */
.sti-num{display:inline-flex;align-items:center;gap:2px;height:30px;padding:0 3px;border-radius:var(--dm-r-field);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent)}
@supports (corner-shape:squircle){.sti-num{corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
.sti-num .ib{width:24px;height:24px}
.sti-num .ib[aria-disabled="true"]{color:var(--dm-dis);background:none;cursor:not-allowed}
.sti-num .num{min-width:22px;text-align:center;font-size:13px}
.sti-seg.seg2 button{height:24px;padding:0 10px;font-size:12px}
.sti-rule{display:flex;flex-wrap:wrap;align-items:center;gap:6px;padding:var(--dm-s-1) 0 var(--dm-s-2)}
.sti-in{width:64px;height:30px;padding:0 var(--dm-s-2);border:0;outline:0;border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);font:inherit;font-size:13px;font-variant-numeric:tabular-nums;color:var(--dm-fg);transition:box-shadow var(--dm-t-fast)}
@supports (corner-shape:squircle){.sti-in{corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
.sti-in:focus{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
/* where a branch's paths go */
.sti-link{display:inline-flex;align-items:center;gap:var(--dm-s-2);min-width:0;max-width:100%;height:28px;font-size:13px;color:var(--dm-fg);white-space:nowrap}
.sti-link>span:last-child{min-width:0;overflow:hidden;text-overflow:ellipsis}
:where([data-c]) button.sti-link{padding:0 var(--dm-s-2);margin-left:-8px;border-radius:var(--dm-r-sm);transition:background var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){:where([data-c]) button.sti-link:hover{background:var(--dm-row)}}
.sti-p{margin:0;padding:2px 0 var(--dm-s-2);font-size:12.5px;color:var(--dm-muted)}
/* the menus: a field list grouped by step, and the choices */
.sti-pk,.sti-dp{min-width:208px;max-width:288px}
.sti-dp{width:288px;max-height:300px;overflow-y:auto;scrollbar-width:thin}
.sti-dp .ph{display:flex;align-items:center;gap:var(--dm-s-2)}
.sti-dp .mi{display:grid;grid-template-columns:auto auto minmax(0,1fr);gap:var(--dm-s-2);padding-left:34px}
.sti-dp .mi .r{min-width:0;margin-left:0;text-align:right;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.sti-pk .mi .av{width:20px;height:20px;font-size:9px}
.sti-off{flex:none}
.sti-live{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
.sti-body{position:relative}
.sti-body.in>*{animation:enter var(--dm-t) var(--dm-ease) backwards}
