.rdr-nd[data-st="ok"] .rdr-ns .i{width:12px;height:12px}
.rdr-ti{width:18px;height:18px;flex:none;display:grid;place-items:center;border-radius:calc(5px * var(--dm-rk));background:var(--dm-rdr-kb,var(--dm-chip));color:var(--dm-rdr-kf,var(--dm-fg2))}
.rdr-ti .i{width:11px;height:11px}
.rdr [data-k],.rdr-dw [data-k]{--dm-rdr-kb:var(--dm-chip);--dm-rdr-kf:var(--dm-fg2);--dm-rdr-kc:var(--dm-faint)}
.rdr [data-k="trigger"],.rdr-dw [data-k="trigger"]{--dm-rdr-kb:var(--dm-pp-bg);--dm-rdr-kf:var(--dm-pp);--dm-rdr-kc:var(--dm-pp)}
.rdr [data-k="ai"],.rdr-dw [data-k="ai"]{--dm-rdr-kb:var(--dm-pl-bg);--dm-rdr-kf:var(--dm-pl);--dm-rdr-kc:var(--dm-pl)}
.rdr [data-k="model"],.rdr-dw [data-k="model"]{--dm-rdr-kb:var(--dm-pl-bg);--dm-rdr-kf:var(--dm-pl);--dm-rdr-kc:color-mix(in srgb,var(--dm-pl) 75%,var(--dm-surface))}
.rdr [data-k="tool"],.rdr-dw [data-k="tool"]{--dm-rdr-kb:var(--dm-pt-bg);--dm-rdr-kf:var(--dm-pt);--dm-rdr-kc:var(--dm-pt)}
.rdr :is([data-k="app"],[data-k="output"]),.rdr-dw :is([data-k="app"],[data-k="output"]){--dm-rdr-kb:var(--dm-pb-bg);--dm-rdr-kf:var(--dm-pb);--dm-rdr-kc:var(--dm-pb)}
.rdr [data-k="branch"],.rdr-dw [data-k="branch"]{--dm-rdr-kb:var(--dm-py-bg);--dm-rdr-kf:var(--dm-py);--dm-rdr-kc:var(--dm-py)}
.rdr [data-k="wait"],.rdr-dw [data-k="wait"]{--dm-rdr-kb:var(--dm-pk-bg);--dm-rdr-kf:var(--dm-pk);--dm-rdr-kc:var(--dm-pk)}
.rdr [data-k="approval"],.rdr-dw [data-k="approval"]{--dm-rdr-kb:var(--dm-pm-bg);--dm-rdr-kf:var(--dm-pm);--dm-rdr-kc:var(--dm-pm)}
